#define DT_DRV_COMPAT zephyr_adc_emul

#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/drivers/adc/adc_emul.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(adc_emul, CONFIG_ADC_LOG_LEVEL);

/**
 * @brief Structure for ADC emulator configuration
 *
 * @param num_channels The number of channels supported by the emulator
 * @param vref_mv The reference voltage in millivolts
 */
struct adc_emul_config {
	uint8_t num_channels;
	uint16_t vref_mv;
};

/**
 * @brief Structure for ADC emulator data
 *
 * @param const_values Pointer to array holding the constant values for each
 *                     channel.
 */
struct adc_emul_data {
	uint32_t *const_values;
};

static int adc_emul_channel_setup(const struct device *dev,
				  const struct adc_channel_cfg *channel_cfg)
{
	const struct adc_emul_config *config = dev->config;

	if (channel_cfg->channel_id >= config->num_channels) {
		LOG_ERR("Invalid channel id %d", channel_cfg->channel_id);
		return -EINVAL;
	}

	/* All other settings are ignored by the emulator */

	return 0;
}

static int adc_emul_read(const struct device *dev,
			 const struct adc_sequence *sequence)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;
	int error = 0;
	uint32_t val;
	size_t buf_len;

	buf_len = sequence->buffer_size;

	for (uint32_t i = 0; i < sequence->channels; i++) {
		uint8_t channel_id = i;

		if (sequence->options) {
			channel_id = sequence->options->extra_samplings * i;
		}

		if (channel_id >= config->num_channels) {
			LOG_ERR("Invalid channel id %d", channel_id);
			error = -EINVAL;
			break;
		}

		val = data->const_values[channel_id];

		switch (sequence->resolution) {
		case 8:
			if (val > 255) {
				val = 255;
			}
			break;
		case 10:
			if (val > 1023) {
				val = 1023;
			}
			break;
		case 12:
			if (val > 4095) {
				val = 4095;
			}
			break;
		case 16:
			if (val > 65535) {
				val = 65535;
			}
			break;
		default:
			LOG_ERR("Unsupported resolution %d",
				sequence->resolution);
			error = -ENOTSUP;
			break;
		}
		if (error) {
			break;
		}

		if (buf_len < sizeof(val)) {
			LOG_ERR("Provided buffer is too small");
			error = -ENOMEM;
			break;
		}

		memcpy(sequence->buffer, &val, sizeof(val));
		buf_len -= sizeof(val);
	}

	return error;
}

#ifdef CONFIG_ADC_ASYNC
static int adc_emul_read_async(const struct device *dev,
			       const struct adc_sequence *sequence,
			       struct k_poll_signal *async)
{
	/* TODO(b/262220532): implement */
	return -ENOTSUP;
}
#endif /* CONFIG_ADC_ASYNC */

static const struct adc_driver_api adc_emul_driver_api = {
	.channel_setup = adc_emul_channel_setup,
	.read = adc_emul_read,
#ifdef CONFIG_ADC_ASYNC
	.read_async = adc_emul_read_async,
#endif /* CONFIG_ADC_ASYNC */
};

int adc_emul_const_value_set(const struct device *dev, uint8_t channel,
			     uint32_t value)
{
	const struct adc_emul_config *config = dev->config;
	struct adc_emul_data *data = dev->data;

	if (channel >= config->num_channels) {
		return -EINVAL;
	}

	data->const_values[channel] = value;

	return 0;
}

static int adc_emul_init(const struct device *dev)
{
	struct adc_emul_data *data = dev->data;
	const struct adc_emul_config *config = dev->config;

	if (data->const_values == NULL) {
		LOG_ERR("const_values must be provided");
		return -EINVAL;
	}

	for (int i = 0; i < config->num_channels; i++) {
		data->const_values[i] = 0;
	}

	return 0;
}

#define ADC_EMUL_INIT(n)                                                       \
	static uint32_t adc_emul_const_values_##n[DT_INST_PROP(n, num_channels)]; \
	static struct adc_emul_data adc_emul_data_##n = {                       \
		.const_values = adc_emul_const_values_##n,                     \
	};                                                                     \
	static const struct adc_emul_config adc_emul_config_##n = {             \
		.num_channels = DT_INST_PROP(n, num_channels),                 \
		.vref_mv = DT_INST_PROP(n, vref_mv),                           \
	};                                                                     \
	DEVICE_DT_INST_DEFINE(n, adc_emul_init, NULL, &adc_emul_data_##n,       \
			      &adc_emul_config_##n, POST_KERNEL,               \
			      CONFIG_ADC_INIT_PRIORITY, &adc_emul_driver_api);

DT_INST_FOREACH_STATUS_OKAY(ADC_EMUL_INIT)
